INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roblox', 'Roblox is a massively multiplayer online platform marketed towards creators and players of all ages. It allows its users to create their own virtual worlds using a variety of objects, in which they or other members may enter and socialize within. Worlds created on Roblox can be scripted using a sandboxed edition of Lua 5.1 to affect events that occur in-game and create different scenarios.' FROM games WHERE igdb_id = 17269 ON CONFLICT (game_id, language_code) DO NOTHING;
