INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman: Act Zero', 'Bomberman: Act Zero is an action video game developed by Hudson Soft and published by Konami for the Xbox 360 in 2006. It is noteworthy for its departure from standard titles in the Bomberman series; it features more realistic graphics and a dark, dystopian future setting.' FROM games WHERE igdb_id = 6925 ON CONFLICT (game_id, language_code) DO NOTHING;
