INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winning Eleven: Pro Evolution Soccer 2007', '​Winning Eleven: Pro Evolution Soccer 2007 is a soccer simulation game developed and published by Konami. The game offers various modes, including exhibition matches, cup competitions, and an enhanced Master League. It features licensed international teams such as Argentina, the Netherlands, Italy, Spain, and Sweden, along with several licensed club teams. The gameplay emphasizes realistic soccer mechanics with improved artificial intelligence and more responsive controls.' FROM games WHERE igdb_id = 2484 ON CONFLICT (game_id, language_code) DO NOTHING;
