INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s African Safari', 'Players discover Africa''s untamed wild as they hunt a variety of African big game in pursuit of the ultimate hunting challenge - the feared Big Five - leopards, lions, elephants, rhinos and Cape buffalo. In Cabela''s African Safari, players choose from seven, 10 or 14 day safaris including open safari, game tracking, baiting and herd hunting missions. The game features over 30 exotic species of animals including sable, kudu, gemsbok, eland, waterbuck, and impala.' FROM games WHERE igdb_id = 6931 ON CONFLICT (game_id, language_code) DO NOTHING;
