INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cabela-s-alaskan-adventures', 6932, '2006-09-09', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jn9zlxmp1yjtoltjkcab.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Alaskan Adventures', 'Cabela''s Alaskan Adventures is the ultimate hunting and fishing adventure to North America''s last frontier. Experience all that Alaska has to offer, as you go on 38 hunting and fishing adventures across vast tundra. For the first time in one game, you will be able to hunt trophy animals, fish, bird hunt, dog sled through the Alaskan Artic, and compete in various outdoor-themed contests. It will take every ounce of skill and strategy to hunt or catch that record-breaking trophy. It''s as true-to-life as it gets! Go exploring or get to your next hunting spot in a snowmobile, truck or ATV All new shooting features and controls including Hunter''s Sense, Gun Sway and Drop Dot Incredibly realistic terrain including vast tundra, dense forests, river deltas, rocky slopes and more.' FROM games WHERE igdb_id = 6932 ON CONFLICT (game_id, language_code) DO NOTHING;
