INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Full Auto 2: Battlelines', 'Full Auto 2: Battlelines revs up its engines as the next generation of high-speed combat racing. The game is the sequel to the award-winning Full Auto, and this new standard of vehicular mayhem is exclusively available for the PlayStation 3 as a launch title. In Full Auto 2: Battlelines, the once-pleasant districts of Meridian City are turning into battle zones, rife with automotive destruction. Use explosive weapons, high-speed vehicles and skillful technologically-groundbreaking demolition of the environment to defeat your opponents and claim the city as your own.' FROM games WHERE igdb_id = 7309 ON CONFLICT (game_id, language_code) DO NOTHING;
