INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Honeycomb Beat', 'The first music-driven puzzle game for the Nintendo DS, Honeycomb Beat features intuitive touch screen gameplay and more than 200 unique puzzles to energize your mind. Solve each puzzle by touching on a Honeycomb tile, which will change the colors of the tiles around it. Line up tiles of the same color to eliminate them or create different shapes and patterns. Solve mind-bending challenges of increasing complexity in Puzzle Mode, or play through Evolution Mode where the board advances upwards and you have to eliminate lines before it''s too late.' FROM games WHERE igdb_id = 20685 ON CONFLICT (game_id, language_code) DO NOTHING;
