INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Chicken: Pirates', 'A one-legged captain, a gunner, a cutlass-wielding chicken and a treasure hunter... the island is home to countless perils, hidden extras and mysteries. The lords of the island are by no means willing to surrender themselves and their treasure without a fight. Crazy Chicken Pirates 3D is a point & shoot action game where you take aim at birds as they scurry through the island and plunge bravely into the waves for a desperate counterattack. You only have 90 seconds to complete your raid by slaying pirates and collecting all hidden treasures.' FROM games WHERE igdb_id = 23673 ON CONFLICT (game_id, language_code) DO NOTHING;
