INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enchanted Arms', 'An action adventure role-playing game that has a linear storyline with a somewhat open world to travel through and explore. Along with 4 main playable characters mix your team up with over 100 collectable creatures scattered throughout the game. Uses a turn based battle system with each side on its own 3 by 4 square grid area across from each other. Characters can move a set number of squares on the grid each turn and skills have different area of effect patterns.' FROM games WHERE igdb_id = 6988 ON CONFLICT (game_id, language_code) DO NOTHING;
