INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Monkey Ball Touch & Roll', 'Super Monkey Ball Touch & Roll brings the Super Monkey Ball series to the DS. Featuring a similar selection of party games and 50 different characters, this newest entry builds on the previous versions of the game. Ten different worlds will challenge your monkey-controlling skills. Also, touch-screen controls and wireless play have been implemented to take advantage of the DS platform.' FROM games WHERE igdb_id = 20489 ON CONFLICT (game_id, language_code) DO NOTHING;
