INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phoenix Wright: Ace Attorney - Justice for All', 'The second game in the popular court room battle series from Japan introduces four new cases featuring new characters, plot twists and gameplay features. Players resume the role of Phoenix Wright, a defense attorney who must prove his client''s innocence against the toughest of odds and most ruthless of adversaries. Players must exercise their legal prowess as they collect evidence, examine witnesses, analyses testimonies and seek the truth to ensure that justice prevails.' FROM games WHERE igdb_id = 1427 ON CONFLICT (game_id, language_code) DO NOTHING;
