INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer: Mark of Chaos', 'Design your own personal army and take up arms against the hordes of Chaos. Crush your enemies beneath your feet and bring them justice to the Warhammer world. Warhammer - Mark of Chaos gives you unprecedented control over the tactics, appearance and unit content of Chaos, Empire, Skaven and High Elf armies. Make your mark!' FROM games WHERE igdb_id = 7241 ON CONFLICT (game_id, language_code) DO NOTHING;
