INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris DS', 'You can rediscover the timeless puzzle game Tetris on your Nintendo DS with Tetris DS. Now you can choose from six different game modes, all of which take advantage of the DS''s touch screen. Each game mode features a theme from another Nintendo franchise, such as The Legend of Zelda or Metroid. You can challenge up to nine other players using one cartridge for local multiplayer play or three other players around the world with the DS''s Wi-Fi connection.' FROM games WHERE igdb_id = 18599 ON CONFLICT (game_id, language_code) DO NOTHING;
