INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cricket 07', 'Cricket 07 is a cricket game from EA Sports and developed by HB Studios.It features a number of game types, including limited overs matches (50, 20, 10 or 5 overs), 4-day first-class matches and full-length test matches.You may select different pitches and different weather conditions in different venues.' FROM games WHERE igdb_id = 10619 ON CONFLICT (game_id, language_code) DO NOTHING;
