INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bookworm Adventures', 'Help Lex battle through books in a spelling sensation of epical proportions! Vanquish villains, whomp foes and annihilate over 150 enemies. Increase your word power with fantastic gems, potions and treasures. With exciting mini-games and brilliant bonus modes, it''s the ultimate test of vocabularic valor!' FROM games WHERE igdb_id = 14885 ON CONFLICT (game_id, language_code) DO NOTHING;
