INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'March of the Penguins', 'The critically acclaimed story of love and survival in the world''s harshest environment becomes a wondrous videogame journey! In the video game adaptation of the Oscar-winning film March of the Penguins you’ll guide loveable Emperor Penguins on their incredible journey for survival, defying the elements, in the name of life and family. This magical "edutainment" quest stars some of the most beloved animals on Earth ... and featuring some of the most dangerous predators and environments ever encountered.' FROM games WHERE igdb_id = 20648 ON CONFLICT (game_id, language_code) DO NOTHING;
