INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atlantis-sky-patrol', 16182, '2006-08-23', 89, 'https://images.igdb.com/igdb/image/upload/t_cover_big/m4kvvecizi7tjqayldlp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uy4s81ggxro46b43m4su.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantis Sky Patrol', 'This frenetic marble-popping adventure puts you in charge of how fast each level will end. Knock out doomsday devices on each of the 100 levels in the game by matching marble colors in sets of three. To finish off the device and move on to the next round, simply destroy the cleverly-placed static orbs that continually allow additional chains to fill the track. Easy to learn, but difficult to master, this puzzler is nearly impossible to put down!' FROM games WHERE igdb_id = 16182 ON CONFLICT (game_id, language_code) DO NOTHING;
