INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Weapon Deluxe', 'It''s shoot-''em-up arcade action at its best! Use an incredible assortment of heavy artillery to blast away enemy tanks and planes, and fight your way to victory. What are you waiting for? Pull yourself up by your bootstraps and get into the action! Blast your way through 19 missions packed with peril.' FROM games WHERE igdb_id = 27812 ON CONFLICT (game_id, language_code) DO NOTHING;
