INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben 10: Battle Ready', 'Gwen and Grandpa Max have sent Ben to an abandoned Sumo Slammer Card factory to train with his new found powers, but the simple exercises turn into a trial when the evil Vilgax detects the Omnitrix''s power signal and sends his robot drones to retrieve the device at any cost! Training can wait. It''s hero time!
