INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-empires-v', 15614, '2006-09-01', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co41uf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars2u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Empires V', 'Space Empires V is the latest edition in the Space Empires series. This new chapter completely updates the UI and takes the player into a real-time rendered 3D universe. Watch space battles played out in glorious detail and realistic effects. Expand, Explore, Exploit, and Exterminate in a huge living breathing galaxy. New features abound with political alliances between multiple empires, a top-down ship design system, a hexagonal movement grid, and many more. Due to player demand, the game is completely ''moddable'' and even adds a scriptable AI system to the mix. Space Empires V boldly takes the next step in the genre of space strategy.
