INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jan Sangoku Musou', 'The game is played against the characters of "Dynasty Warriors Series," Koei game based on the Sanguo Zhi in China, but it is an authentic mahjong game which adopts an algorithm that does not have a kind of insane technique that is common in character mahjong games. This game is based on the mahjong software "Mahjong Taikai" released by Koei.' FROM games WHERE igdb_id = 64360 ON CONFLICT (game_id, language_code) DO NOTHING;
