INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guild Wars: Nightfall', 'In Guild Wars Nightfall, the third campaign in the award-winning Guild Wars universe, you will never face danger alone. Not only can you group with any of millions of players worldwide, but now, for the first time ever, you''ll be able to band together with customizable Heroes that will not only fight by your side, but level up with your character and follow your orders as you fight to hold back the night.' FROM games WHERE igdb_id = 8947 ON CONFLICT (game_id, language_code) DO NOTHING;
