INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rat Hunter', 'Rat Hunter is a traditional first-person-shooter that firmly takes its inspiration from Doom, Quake and other older titles. It''s all about fast-paced shooting action and the design is kept intentionally simple. You will gain no benefit from headshots, there''s no cover system and no iron sights.' FROM games WHERE igdb_id = 54308 ON CONFLICT (game_id, language_code) DO NOTHING;
