INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB 06: The Show', 'MLB ''06: The Show is a baseball video game for PlayStation 2 and PSP. The game was produced by Sony Computer Entertainment, primarily by SCE''s San Diego Studio, which was formerly known as 989 Sports. It was the only first-party MLB-licensed video game for the 2006 season drawing attention to the brand and franchise. The game was one of two MLB-licensed games for 2006 along with Major League Baseball 2K6.' FROM games WHERE igdb_id = 20525 ON CONFLICT (game_id, language_code) DO NOTHING;
