INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunted House', 'As can be inferred from the title, Haunted House is a Halloween themed escape game, though it is not particularly scary due to the child friendly art style and lack of jump scares, etc. The game was developed by KMart and features links to their website to buy Halloween costumes of various characters that are found in the game.' FROM games WHERE igdb_id = 256077 ON CONFLICT (game_id, language_code) DO NOTHING;
