INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('orcs-and-elves', 21527, '2006-05-01', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co965v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rbygl1o8pzeshbtqpkxx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orcs & Elves', 'Orcs & Elves'' is a turn-based role-playing game, played from a first person perspective. Each individual action by the player counts as a "turn", whether that be movement, using an item or weapon or casting a spell in which other foes will also move and attack in turns following each. Each forward move by the player is done on an invisible grid that makes up each level in order to retain the turn-based element while appearing more like a first person adventure due to its fast paced nature.' FROM games WHERE igdb_id = 21527 ON CONFLICT (game_id, language_code) DO NOTHING;
