INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Left Behind: Eternal Forces', 'Wage a war of apocalyptic proportions in Left Behind: Eternal Forces, a real time strategy game based upon the best-selling book series created by Tim LaHaye and Jerry Jenkins. Conduct physical and spiritual warfare, recover ancient scriptures and command your forces through intense battles. You will also have the opportunity to play multi-player games with up to 8 players via LAN or over the internet.' FROM games WHERE igdb_id = 20614 ON CONFLICT (game_id, language_code) DO NOTHING;
