INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Essentials', 'Tom Clancy''s Splinter Cell: Essentials is an action-adventure video game with heavy emphasis on stealth. It is part of the Splinter Cell series and was released for the PlayStation Portable handheld system. It was developed by Ubisoft Montreal and published by Ubisoft on March 21, 2006 in North America. It is the fourth entry in the series and was powered by Unreal Engine 2.' FROM games WHERE igdb_id = 22632 ON CONFLICT (game_id, language_code) DO NOTHING;
