INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wildlife Park 2', 'Now''s the chance to build the Zoo of your dreams! Just like in a real Zoo, your animals must receive complete care. Feed them, train them, cure them and even relocate them. Observe their realistic interactions with one another, the landscape, the play equipment and even Zoo visitors.' FROM games WHERE igdb_id = 17491 ON CONFLICT (game_id, language_code) DO NOTHING;
