INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto: Uzumaki Chronicles 2', 'Naruto: Uzumaki Chronicles 2 is an action RPG where players travel across a map, completing missions to gain experience points for unlocking new abilities and boosting their character''s stats. The story mode, set after the Sasuke Recovery Mission, shows Naruto facing the puppet-using Shirogane clan.' FROM games WHERE igdb_id = 21231 ON CONFLICT (game_id, language_code) DO NOTHING;
