INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoopy vs. The Red Baron', 'Snoopy vs. the Red Baron is a flight combat game released on the PlayStation 2, PlayStation Portable, and PC in 2006. As the name implies, the protagonist is Snoopy, the dog in Charles M. Schulz''s comic strip, Peanuts. The game is based on one of the most famous Snoopy alter egos: a World War I flying ace battling against Manfred von Richthofen, the Red Baron, the Flying Circus: Jagdgeschwader 1, the Austro-Hungarian Empire, and other enemies of the war.' FROM games WHERE igdb_id = 2756 ON CONFLICT (game_id, language_code) DO NOTHING;
