INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirates of the Caribbean: Dead Man''s Chest', 'Pirates of the Caribbean 2: Dead Man’s Chest is a swashbuckling action-adventure for the Sony PSP and Nintendo DS. Players play as the notorious (or at least ‘heard of’) pirate Jack Sparrow. Throughout the game the player sword fights with the undead, swings from the rigging, escapes from cannibals, and liberates booby-trapped treasure in a non-linear, action-packed 3D game that emphasizes pick-it-up/put-it-down game play.' FROM games WHERE igdb_id = 20542 ON CONFLICT (game_id, language_code) DO NOTHING;
