INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lost-planet-extreme-condition', 1913, '2006-12-21', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45g0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arz4p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Planet: Extreme Condition', 'The game is played through a third person over-the-shoulder view. Players are allowed to switch between first person and third person at any moment. Players either travel on foot or ride various types of mechanized suits called Vital Suits (VSs). VSs carry heavy weapons such as chainguns and rocket launchers. They can pick up weapons lying on the ground and fire multiple weapons at once. On foot, players are able to use a grappling hook to pull themselves up to normally hard-to-reach places, or to hook onto a VS and hijack it. Driving VSs and using certain weapons requires thermal energy. Also, the planet''s cold temperature causes the characters'' thermal energy level to continually decrease. Players can replenish their thermal energy level by defeating enemies or activating data posts. Data posts also allow players to use their navigational radars to see incoming enemies. Each of the 11 levels is accompanied by a boss, which can be either a VS or a large Akrid.' FROM games WHERE igdb_id = 1913 ON CONFLICT (game_id, language_code) DO NOTHING;
