INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-elder-scrolls-iv-oblivion', 59, '2006-03-20', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8fpz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m4m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elder Scrolls IV: Oblivion', 'The Elder Scrolls IV: Oblivion, the fourth game in the Elder Scrolls story, is set within the province of Cyrodiil, the heartland and Imperial capital of Tamriel. Emperor Uriel Septim VII is assassinated in flight from his own palace, but just before he dies he passes on to you the mystic Amulet of Kings. The adventure proper begins with the quest to find Uriel''s lost and illegitimate son who is the only heir to the throne. In a world where the forces of darkness seek their ultimate dominion over the ranks of man and mer alike, you alone stand between the future of Tamriel and the gates of Oblivion.' FROM games WHERE igdb_id = 59 ON CONFLICT (game_id, language_code) DO NOTHING;
