INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bejeweled 2 Deluxe', 'Bejeweled 2 Deluxe is the enhanced, standalone version of the free online puzzle game of similar name. It builds on the original award-winning game, with the same basic objective of matching "jewels" in a grid by threes, by swapping adjacent jewels of different colors. Sharper graphics and more special effects improve the experience.' FROM games WHERE igdb_id = 14806 ON CONFLICT (game_id, language_code) DO NOTHING;
