INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Are Empty', 'You Are Empty is a first-person shooter video game based in a fictionalized postwar Soviet Union. The game begins with the protagonist waking up in a ruined hospital, and it soon becomes clear that the populace has been afflicted by mutation and madness. He then must battle to stay alive and unravel the mystery.' FROM games WHERE igdb_id = 54651 ON CONFLICT (game_id, language_code) DO NOTHING;
