INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Test Drive Unlimited', 'Test Drive Unlimited is the ultimate automotive experience for car and bike enthusiasts alike. Visit the most sophisticated car and bike dealers to purchase new vehicles or simply take them for a spin. Collect and trade rare performance parts and customize each vehicle to make it one-of-a-kind. Test Drive Unlimited challenges players online to experience the most exotic and fastest vehicles on more than 1000 miles of diverse Hawaiian roads. Gamers win races, challenges, missions and tournaments to earn credits and purchase new cars, bikes, rare performance parts, clothes, apparel, homes and garages.' FROM games WHERE igdb_id = 7215 ON CONFLICT (game_id, language_code) DO NOTHING;
