INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race: The WTCC Game', 'Race: The WTCC Game is the first ever game to be focused on the hard hitting, intense action of the exciting WTCC championship which is exploding in popularity all over the world. Based on WTCC, one of only three official FIA world championships next to Formula 1 and WRC, RACE features the complete WTCC championship season of 2006, all the cars, drivers and locations, including several official tracks and cars brand new to the racing game genre.
