INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Supernova', 'The hottest revolution and bestselling video game in the music game category returns to its arcade roots with Dance Dance Revolution Supernova, the first arcade version to be released in North America in 6 years. Dance Dance Revolution Supernova uses a completely new hardware engine and is the largest game in the series. Players will have access to over 300 songs from different musical genres and 2000+ dance step patterns. Dance Dance Revolution Supernova is a brand new evolution in the DDR series and expands on every aspect of what made the original series innovative, fun and addictive.' FROM games WHERE igdb_id = 6779 ON CONFLICT (game_id, language_code) DO NOTHING;
