INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bratz: Forever Diamondz', 'Yasmin, Cloe, Sasha, and Jade are back for a brand new adventure sending them across the country in search of the hottest fashion designer. Players experience unique adventures through the eyes of the four playable characters, in detailed open world environments, as they compete for a spot in "America Rocks Fashion" TV show. Fans discover new features that include a figure skating competition and the ability to adopt a pet to train, dress, accessorize and showcase in competitions.' FROM games WHERE igdb_id = 3835 ON CONFLICT (game_id, language_code) DO NOTHING;
