INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Abbey', 'The ambitious project takes adventure fans to the gloomy world of the middle Ages. An old abbey is the scene of a series of mysterious murders, and only one man can put a stop to the slaughter. In the role of the Grand Inquisitor Leonardo and his assistant Bruno, the player''s task is to shed light on the mystery.' FROM games WHERE igdb_id = 17628 ON CONFLICT (game_id, language_code) DO NOTHING;
