INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei Devil Summoner: Raidou Kuzunoha vs. The Soulless Army', 'Raidou Kuzunoha is a private detective in Japan''s Taishou Period of the early 1900s, but he''s much more than just a well-dressed crime scene investigator; he also has the power to capture and conjure demons to do his bidding. Take control of Raidou and his otherworldly companions, guide them through thrilling episodes of action and intrigue, and learn the incredible secrets of the Soulless Army. Detailed real-time combat sequence with swords, guns, combo attacks, and devilish helpers. Photorealistic graphics that transport the player to 1930s Japan.' FROM games WHERE igdb_id = 20640 ON CONFLICT (game_id, language_code) DO NOTHING;
