INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pizza-frenzy-deluxe', 27786, '2006-08-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zap.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/efsunsqwaipkszt1yj5p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizza Frenzy Deluxe', 'The game contains three game modes based on the same principle. Shown from a top-down view, the player visits different cities where a certain number of pizzas need to be delivered. Before starting a game, the player can select the main topping to offer in that city. Each game, there are two or more pizza houses, one for each type of topping. At irregular intervals, icons with customers appear, requesting a pizza with a specific topping. The player needs to click them and take them back to the delivery house. For each delivered pizza, a tip can be picked up and after a perfect game a zeppelin dropping money appears.' FROM games WHERE igdb_id = 27786 ON CONFLICT (game_id, language_code) DO NOTHING;
