INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sneak King', 'The game is Sneak King, and the object is surprise. Now''s your chance to step into the royal shoes of the King himself as you silently unleash hot sandwiches on the hungry citizens of this famished world. All of your covert gaming skills will be put to the test as you take on the role of the slickest sneaker on the planet: the Sneak King.' FROM games WHERE igdb_id = 2730 ON CONFLICT (game_id, language_code) DO NOTHING;
