INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Battle Network 6: Cybeast Falzar', 'In Mega Man Battle Network 6, Lan''s father has received a job transfer and the family moves to Cyber City, a town known for conducting various technological experiments. Lan will meet new people and build new friendships in the real world while Mega Man befriends helpful Navis and encounters dangerous new enemies on the virtual plane. Together they will face threats far more powerful and perilous than they ever have before.' FROM games WHERE igdb_id = 1764 ON CONFLICT (game_id, language_code) DO NOTHING;
