INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('la-street-racing', 27553, '2006-12-01', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coazj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqib4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LA Street Racing', 'LA Street Racing is a street racing game set in Los Angeles where players climb from 61st place to challenge the underground champion Matt Peacock. Players start with a basic car and compete in high-stakes races at various locations across LA, betting car parts and eventually whole vehicles in pink slip races. The progression system features four prestige levels, each unlocking new racing locations and tougher opponents. Car customization involves strategic decisions about part compatibility and performance trade-offs, as mixing different upgrade tiers affects handling. The racing model emphasizes realistic vehicle physics, requiring careful braking and cornering techniques, while rewarding clean driving with nitrous boosts. The game includes multiplayer support for up to eight racers online.' FROM games WHERE igdb_id = 27553 ON CONFLICT (game_id, language_code) DO NOTHING;
