INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo HD Concept', 'Gran Turismo HD Concept was the first installment of the Gran Turismo racing series to be released on the PlayStation 3. It was made available as a free download on the PlayStation Store. A Blu-ray Disc version, called "Install Disc", was released in Japan in limited quantities in September 2007. This game was intended to be a sneak preview, in the likes of Gran Turismo Concept, preceding the release of a full version title but the Gran Turismo HD project was canceled and replaced by Gran Turismo 5 Prologue.' FROM games WHERE igdb_id = 1598 ON CONFLICT (game_id, language_code) DO NOTHING;
