INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-a-Move: Deluxe', 'Join Bob and Bub plus new characters, never before seen games and ways to play including spooky Ghost Mode! Pop matching colored bubbles to solve puzzles in a variety of game types including head-to-head play. Whether you are a first-timer or an expert bubble launcher, you will be sure to find brain-teasing fun in the over 1000 puzzles available in Bust-A-Move Deluxe!' FROM games WHERE igdb_id = 84162 ON CONFLICT (game_id, language_code) DO NOTHING;
