INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fox Command', 'Star Fox Command lets you hop into your fight through a unique branching storyline of missions, all rendered in gorgeous 3-D. This game brings a whole new strategic element to the series, with a commander''s view of the mission. Using the touch screen, players can draw the routes they and their teammates will take. Battle the enemies they encounter as they take over bases and strategically advance across the map. Players can also blow their friends out of the sky, as they dogfight 8 players over a local wireless connection -- or take on 4 players from around the world on Nintendo Wi-Fi Connection.' FROM games WHERE igdb_id = 20556 ON CONFLICT (game_id, language_code) DO NOTHING;
