INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Villagers: A New Home', 'Care for and nurture a tribe of little people by teaching them the basics of survival. They need to become farmers, builders, scientists, parents and make decisions about unpredictable ''island events''! Guide their day-to-day lives and help them explore and restore their new home. As your village grows and prospers, your villagers become curious about their mysterious new island home and the secrets it holds.' FROM games WHERE igdb_id = 14909 ON CONFLICT (game_id, language_code) DO NOTHING;
