INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 07', 'NHL 07 is an ice hockey video game, released in 2006 as the successor to NHL 06. The game improved the series'' gameplay with more realistic features, such as stickhandling and a wider variety of controller schemes. The Xbox 360 version features a completely revamped game and graphics engine from the predecessor, while the other versions are left behind with the old engine. It is the only game in the series to have a PSP version, the last installment to be released on Xbox, and the first installment to be released on Xbox 360.' FROM games WHERE igdb_id = 5964 ON CONFLICT (game_id, language_code) DO NOTHING;
