INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchu: Dark Secret', 'Tenchu: Dark Secret places you in the shoes of ninja assassins charged with protecting the life of a princess. Stalk your enemies with sword in hand, plant explosive traps in the underbrush, or strike with an assortment of realistic ninja weaponry - the choice is yours. It features over 40 single-player missions and the ability to construct your own weapons and items. Prove your mettle with the metal by challenging friends to a local wireless multiplayer match.' FROM games WHERE igdb_id = 20557 ON CONFLICT (game_id, language_code) DO NOTHING;
