INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Dungeon: Shiren the Wanderer', 'Shiren and his pet weasel Koppa have set out to find golden city El Dorado and the lair of the legendary Golden Condor. Along the way they''ll make new friends, visit caves and dungeons, and kill the heck out of a myriad of monsters in this turn-based roguelike.' FROM games WHERE igdb_id = 78341 ON CONFLICT (game_id, language_code) DO NOTHING;
