INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Fighter 5', 'Virtua Fighter 5 features an all-star cast of 17 fighters, including characters from the previous iterations along with two new characters named El Blaze and Eileen. The game delivers fast-paced, adrenaline-pumping action as players head into battle, taking on a host of popular characters. Players not only achieve victory by defeating highly-skilled opponents, but also by competing for prizes which earn them in-game money allowing them to buy many items at in-game shop. These items allow players to customize their ultimate warrior and become the top Virtua Fighter.' FROM games WHERE igdb_id = 1555 ON CONFLICT (game_id, language_code) DO NOTHING;
