INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons Online', 'Centered in the city of Stormreach, DDO is set on the fictional continent of Xen''drik, in the world of Eberron, a Dungeons and Dragons campaign setting. Xen''drik is a vastly unexplored and wild locale, once the center of the Advanced Giant Civilization, which was destroyed thousands of years before. Players can create their characters following the revised edition of D&D 3.5 rule-set fashion, and play them in both indoor and outdoor environments, including dungeons.' FROM games WHERE igdb_id = 5629 ON CONFLICT (game_id, language_code) DO NOTHING;
