INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feeding Frenzy 2: Shipwreck Showdown', 'Become the biggest fish at the top of the food chain with Feeding Frenzy 2 Shipwreck Showdown, now on the PlayStation Network! Start as the little fish in the ocean and get your ‘eat’ on! Feast upon fish smaller than you and you’ll grow bigger and bigger. Avoid predators, or you’ll become THEIR meal. Feeding Frenzy 2 features 60 levels of underwater fun and above water challenges and local multiplayer Party Games and Frenzyfest modes' FROM games WHERE igdb_id = 8321 ON CONFLICT (game_id, language_code) DO NOTHING;
