INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mushihime-sama Futari', 'Mushihime-sama Futari (虫姫さまふたり Mushihime-sama Futari?, lit. "Bug Princess Duo"), a bullet hell shooter by Cave, was released in arcades on October 27, 2006 and as a sequel to Mushihimesama. Mushihimesama Futari was released on the Xbox 360 in Japan on November 26, 2009. In April 2012, Cave released a port of the game on the iOS platforms, titled Bug Princess 2 (Mushihimesama was also released on the platforms titled Bug Princess).' FROM games WHERE igdb_id = 27626 ON CONFLICT (game_id, language_code) DO NOTHING;
