INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('red-orchestra-ostfront-41-45', 9409, '2006-03-14', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jks.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zmvlo9zufb07thxjvi8b.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Orchestra: Ostfront 41-45', 'Fight in the theatre of war that changed the world forever. Battle alongside your compatriots on some of the most inhospitable environments of the Eastern Front in Red Orchestra: Ostfront 41-45. Red Orchestra places you in the most realistic WWII first-person multi-player combat to date on the PC, allowing the player to fight through some of the most intense combat of the war. You can play as infantry, using a wide range of infantry weapons, or crew one of the many armored combat vehicles available in the game, from half-tracks to the most famous German and Soviet heavy tanks. Engage the enemy with everything in your arsenal, from your bayonet at close quarters up to the massive 122mm cannon on the Soviet IS-2. And if that isn''t enough, find an officer and a radio to call in thunderous artillery strikes to shake the enemy loose.' FROM games WHERE igdb_id = 9409 ON CONFLICT (game_id, language_code) DO NOTHING;
