INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poker Superstars II', 'You''ve been invited back for Season 2! Poker Superstars II raises the stakes with more superstars, a bigger tournament and a brand new poker AI. Import your own photo into the game and become a Poker Superstar. Then get ready to battle through an exciting new tournament structure against 15 of poker''s top players powered by a ''first of its kind'' artificial intelligence system that has learned to win by playing millions of simulated tournaments! The Superstars are ready to win, are you?' FROM games WHERE igdb_id = 15716 ON CONFLICT (game_id, language_code) DO NOTHING;
