INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi: Party On!', 'It is time for a new president of Tamaworld, and the Tamagotchis are setting up an election to see who it will be. The planet is abuzz and some of the characters want to be president. The election managers hold a competition for whoever can do the most good deeds, become the most popular Tamagotchi on the planet and get the most votes. The Tamagotchis set off to become the most popular Tama on the planet and the title of President!' FROM games WHERE igdb_id = 5211 ON CONFLICT (game_id, language_code) DO NOTHING;
