INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melty Blood Act Cadenza Ver. B', 'Melty Blood Act Cadenza Ver. B is an arcade port of Melty Blood Act Cadenza with various changes and upgrades, the most notable of which is the inclusion of White Len as a playable character, with a significantly weakened moveset. It also introduced a fifth button that served as a contextual action depending on the situation and the direction held on the joystick when pressed, such as dodging or throwing. This version can be identified by a dual silhouette of Len and White Len in the logo and the phrase "Through the Looking-Glass, Northern Light transparently".' FROM games WHERE igdb_id = 39601 ON CONFLICT (game_id, language_code) DO NOTHING;
