INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from Bug Island', 'Bug Island is a island full of bugs and the perfect place for Michelle, who is majoring in insect physiology, to work on a report for school. Along come Mike, the typical confident college playboy and Ray, a freshman in college. Arriving on the island, Mike and Ray fight over Michelle who then runs off into the foggy distance and is nowhere to be found. Now Ray needs to find Michelle and get off the island in one piece.' FROM games WHERE igdb_id = 4835 ON CONFLICT (game_id, language_code) DO NOTHING;
