INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brave Story: New Traveler', 'On a day that starts out like any other, an 11-year-old boy''s life is changed forever when his friend Miki suddenly collapses from an unknown illness. Without the means to save her, he grows increasingly distraught when suddenly, a strange voice offers him a second chance: "Beyond the door you can change your destiny!" He soon leaves the real world and journeys to the world of Vision, where, as a novice "Traveler," he will surmount myriad ordeals in hopes of ultimately meeting with the Goddess of Fortune to have a single wish granted.' FROM games WHERE igdb_id = 14607 ON CONFLICT (game_id, language_code) DO NOTHING;
