INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2006 FIFA World Cup', 'Celebrating the 2006 FIFA World Cup Germany - the world''s largest sporting event - 2006 FIFA World Cup brings you to the games with the world''s superstar players, 12 official stadiums that will be used at 2006 FIFA World Cup Germany and stadiums from each qualifying region. Gamers can play as their favorite team from qualification right through to a virtual reproduction of the tournament in Germany.
