INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechAssault: Phantom War', 'MechAssault: Phantom War is one of the games in the popular MechWarrior series and is part of the BattleTech universe created by FASA. Players assume the role of a BattleMech pilot in a 3D environment with a third person view of the combat via the top screen of the DS, while the touch screen displays the inside of the cockpit and acts as the game''s controls.' FROM games WHERE igdb_id = 19195 ON CONFLICT (game_id, language_code) DO NOTHING;
