INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Break ''Em All', 'Players will attempt to break’em all in classic arcade puzzle solving action as they fight their way through more than 3 million variations of randomly generated levels and out-duel challenging bosses. Three unique gameplay modes such as Tokoton, Quest and Survival offer compelling single player action or multiplayer games for 2-8 players via the wireless feature for Nintendo DS. Break’em All is available now on stores shelves across North America with a suggested retail price of $19.95.' FROM games WHERE igdb_id = 20534 ON CONFLICT (game_id, language_code) DO NOTHING;
