INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alex Rider: Stormbreaker', 'Based on Anthony Horowitz''s series of teen spy movies and movie following adventure-seeker Alex Rider. Players embrace the role of Alex Rider to out-spy, outwit and out-cool evil in this thrilling action adventure. Featuring third-person stealth game play, fast-paced racing action, intense fighting and engaging, gadget-based mini-games, players can relive defining moments from the Stormbreaker movie and become the ultimate spy.' FROM games WHERE igdb_id = 2848 ON CONFLICT (game_id, language_code) DO NOTHING;
