INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokobot Plus: Mysteries of the Karakuri', 'Bolt is an apprentice Treasure Master working at Mr. Canewood''s laboratory. With the help of mysterious Tokobots, he will explore many prehistoric ruins to find ancient relics that will put him one step further on his path to be a Treasure Master and find his father. However, he will also change his destiny in other ways.' FROM games WHERE igdb_id = 20663 ON CONFLICT (game_id, language_code) DO NOTHING;
