INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pimp My Ride', 'Pimp My Ride is a simulation/racing game published by Activision. This game is based on the popular MTV show. It was released in 2006 for the Wii, Xbox 360, PlayStation Portable and PlayStation 2 consoles. In the game, players are challenged to pimp out their friends'' cars by Xzibit, transforming something old and rusty into something worthy of displaying on the streets. Cars can be redesigned from bumper to bumper and it will be players’ responsibilities to capture the styles, likes and interests of their clients.' FROM games WHERE igdb_id = 5098 ON CONFLICT (game_id, language_code) DO NOTHING;
