INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Manager 07', 'Keeping the same style carried from the ANSTOSS series to Total Club Manager 2003, in FIFA Manager 07 the player has the complete club at his disposal, from managing the team at all levels, dealing in the transfer market to deciding on where the team should expand facilities (now using an isometric city view not unlike SimCity 3000) and increase stadium capacity. Of course, for those less interested in these aspects, they can all be assigned to the appropriate staff member, but good results can only be obtained by hiring the best staff (the team money and prestige) can buy.' FROM games WHERE igdb_id = 20676 ON CONFLICT (game_id, language_code) DO NOTHING;
