INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torino 2006', 'In the spirit of the winter Olympics, Torino ''06 Olympic Games lets you compete in 15 different events. The game includes such disciplines as bobsledding, figure skating, cross-country skiing, hockey, and biathlon. Up to four players can compete for Olympic glory through head-to-head or sequential gameplay.' FROM games WHERE igdb_id = 6205 ON CONFLICT (game_id, language_code) DO NOTHING;
