INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glory of the Roman Empire', 'Glory of the Roman Empire is the first of three games on the subject (CivCity: Rome, Caesar IV) that came out in 2006. The game has full 3D structures, units and environment. It has dozens of historically inspired structures and environments rendered in full detail in a 3D world. Buildings can be placed easily in every direction.' FROM games WHERE igdb_id = 298 ON CONFLICT (game_id, language_code) DO NOTHING;
