INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('juka-and-the-monophonic-menace', 6479, '2006-04-29', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3rht.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Juka and the Monophonic Menace', 'Taking place in the world of Obla, Juka and the Monophonic Menace follows the journey of young alchemist Juka as he sets out to save his village from the evil Monophonic Menace. Gamers will help guide Juka and his assistant Bufo through six different environments while searching for items, solving puzzles, and defeating the Monophonic Menace''s minions. Juka can shimmy, swim, jump, and climb through the highly detailed environments. Plus, players can enhance and upgrade Juka''s many abilities by completing quests and collecting the various items. Another feature of the game is the alchemy ability. By collecting the six different elemental ingredients, players can mix and create their own items and potions for use during the game. This is the only way to get many of the more powerful potions. Combat is also unique in JUKA. Instead of battling or using magic, players have to quickly match a series of patterns. The quicker and more accurately the patterns are matched, the more damage an enemy takes. Juka and the Monophonic Menace takes many concepts that RPG and action/adventure gamers have come to love and combines them with an innovative combat system and an unique storyline to create a game full of fun, challenge, and excitement.' FROM games WHERE igdb_id = 6479 ON CONFLICT (game_id, language_code) DO NOTHING;
