INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racing Pitch', 'Racing Pitch sets you to be the engine for a racing car! You must use a microphone to mimic the engine sound, which the game will listen and set you blazing forward accordingly. The game features both party games and track challenges, and you can even take a break from racing to fly with a hot-air balloon.' FROM games WHERE igdb_id = 70955 ON CONFLICT (game_id, language_code) DO NOTHING;
