INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Def Jam Fight For NY: The Takeover', 'Def Jam Fight for NY takes the battle for hip-hop domination into the fighting ring. More than 35 hip-hop artists and personalities--including Busta Rhymes, Carmen Electra, Lil'' Kim, Ludacris, Method Man, Redman, Sean Paul, Slick Rick, and Snoop Dogg--face off in brutal wrestling matches. In the ring and on the streets, you''ll join the battle as a New York City street fighter. The game challenges you to develop your own fighting style and seize control of the hip-hop underworld.' FROM games WHERE igdb_id = 23123 ON CONFLICT (game_id, language_code) DO NOTHING;
