INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshi''s Island DS', 'Yoshi''s Island DS is a 2D platformer for the Nintendo DS in the Yoshi''s Island series. It is the sequel to Super Mario World 2: Yoshi''s Island, where Kamek and the Toadies have kidnapped all the babies in the world in search for the star children, a group of seven babies who possess powerful stars in their hearts. While the game is heavily derivative from Super Mario World 2: Yoshi''s Island, including general gameplay, themes, and graphics, the game primarily differentiates itself from its predecessor by taking advantage of the Nintendo DS''s dual screen to display levels while introducing multiple babies to carry on Yoshi''s back, who all have special abilities that are required to complete levels.' FROM games WHERE igdb_id = 20601 ON CONFLICT (game_id, language_code) DO NOTHING;
