INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armadillo Run', 'Armadillo Run is a physics-based puzzle game. You have to build structures with the purpose of getting an armadillo to a certain point in space. There is a selection of building materials, each with different properties, which can be combined to form almost anything. The realistic physics simulation gives you the freedom to solve each level in many different ways.' FROM games WHERE igdb_id = 23137 ON CONFLICT (game_id, language_code) DO NOTHING;
