INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Budokai Tenkaichi 2', 'Tenkaichi 2 is a fighting game with more than 120 playable characters, the biggest amount ever featured in a Dragon Ball game. The main Dragon Adventure mode follows an epic story mode that covers the first Dragon Ball Z saga (Saiyan Saga) right up to the last Dragon Ball GT saga (Dragon Saga), including all of the major battles, making it one of the most comprehensive Dragon Ball Z games.' FROM games WHERE igdb_id = 2252 ON CONFLICT (game_id, language_code) DO NOTHING;
