INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('winback-2-project-poseidon', 6234, '2006-04-25', 54, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8cov.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsqz6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WinBack 2: Project Poseidon', 'In a world where terror takes many forms, a new weapon threatens to shake the balance of power. Freedom''s last hope rests in the hands of three new operatives, who must race against time to recover this doomsday device. The fate of the world hangs by a thread, and a few ticks of the clock means the difference between justice and annihilation. WINBACK 2 brings to the series a new "route" system that lets players experience each mission from the perspective of different operatives. There are 30 intense missions, multiple difficulty levels, and new weapons including the highly-anticipated sniper rifle. The new Winback assault team is comprised of three young, yet combat-proven operatives led by Craig Contrell. Each team member is qualified in six different weapon types and highly-adept at CQB (Close Quarter Battle). They are masters of target identification, engagement and shot placement. In the hands of the player, all of these techniques will be put to the test. The game''s unique shooting action is spread across 30 high-risk operations situated in challenging urban environments and conveyances.' FROM games WHERE igdb_id = 6234 ON CONFLICT (game_id, language_code) DO NOTHING;
