INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('25-to-life', 5714, '2006-01-17', 100, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49pj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/buoevoaq9tg5fan1lwr9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '25 To Life', '25 to Life is designed to place the online tactical action of a squad-based shooter in open urban settings that are reminiscent of the latter-day Grand Theft Auto games. Through two parallel perspectives on the same ongoing conflict, 25 to Life offers play as either a law enforcement officer or a streetwise gangsta. In either case, players are equipped with the tools of their respective trades; cops can make use of their superior training with firearms or call for helicopter air support, while gang members can choose from a wider selection of weapons and use civilian hostages as human shields.
