INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam: Crossfire', 'This is an installment of the anime game series, Gundam, Mobile Suit Gundam: Crossfire takes place Nine months after the Zeon forces attacked, and now the forces of the Earth Federation are about to launch a full blown counter attack. You have the choice of either siding with the earth forces and aid the counter offensive, or join the Zeon and crush the Federation resistance.' FROM games WHERE igdb_id = 7376 ON CONFLICT (game_id, language_code) DO NOTHING;
