INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Blast Ultra', 'Marble Blast Ultra is the latest in the classic Marble Blast series. Suitable for players of any age, Marble Blast Ultra transports you to a futuristic ''astrolab'' arena suspended high in the clouds. Compete against each other by navigating your marbles through moving platforms and dangerous hazards, while collecting rare gems and power-up enhancements, in an effort to complete each course in record time. Compete head to head in Xbox Live ultra blast multiplayer mode.' FROM games WHERE igdb_id = 20503 ON CONFLICT (game_id, language_code) DO NOTHING;
