INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'State of Emergency 2', 'State of Emergency 2 (State of Emergency Revenge in Japan) is the sequel to State of Emergency. The game is available on PlayStation 2. It takes place ten years after the first game. It features more game modes and an enhanced engine. State of Emergency 2 was being developed by VIS Entertainment for Rockstar Games, but the title was continued by SouthPeak Interactive with developer DC Studios.' FROM games WHERE igdb_id = 6162 ON CONFLICT (game_id, language_code) DO NOTHING;
