INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: Legends', 'Singstar Legends offers yet another patch of songs to sing in this 7th game of the series. The objective of the game is to sing songs and sing them well. The game gives points according to player''s performance. There is three difficulty levels to choose from, the easiest one being very forgiving.' FROM games WHERE igdb_id = 15099 ON CONFLICT (game_id, language_code) DO NOTHING;
