INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guilty Gear Judgment', 'Guilty Gear Judgment (ギルティギア・ジャッジメント, Giruti Gia Jajjimento) is a spin-off game of the Guilty Gear series, exclusive to the PlayStation Portable, and the 11th overall installment. It also includes a slimmed-down version of Guilty Gear XX ♯Reload, developed by Arc System Works and published by Majesco in USA and Europe, and SEGA in Japan. It is the first game in the series to be released on PSP outside of Japan.' FROM games WHERE igdb_id = 24196 ON CONFLICT (game_id, language_code) DO NOTHING;
