INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboBlitz', 'RoboBlitz is a humorous, physics-based action game full of inventive gizmos, weapons, characters, and environments. Players take on the role of Blitz, a multi-talented robot who must activate an aging Space Cannon to save his world from a band of maladjusted space pirates.' FROM games WHERE igdb_id = 14822 ON CONFLICT (game_id, language_code) DO NOTHING;
